// Config ya ha mezclado sus campos hacia aquí (includeOtherFields), así que $json
// lleva cuerpo, cabeceras y configuración a la vez.
const cfg = $json;
const headers = cfg.headers || {};

// Retell firma los BYTES que envía. Re-serializar el JSON ya parseado NO sirve:
// un espacio de diferencia y el HMAC no cuadra. Por eso el webhook va con
// rawBody y aquí se recupera el crudo antes que nada.
let crudo = '';
if (typeof cfg.body === 'string') crudo = cfg.body;
else if (cfg.body && cfg.body.data) {
  try { crudo = Buffer.from(cfg.body.data, 'base64').toString('utf8'); } catch (e) { crudo = ''; }
}

let cuerpo = {};
if (crudo) { try { cuerpo = JSON.parse(crudo); } catch (e) { cuerpo = {}; } }
if (!crudo && cfg.body && typeof cfg.body === 'object' && !cfg.body.data) cuerpo = cfg.body;

// Retell manda varios eventos por llamada (call_started, call_ended,
// call_analyzed). El análisis solo existe en el último: los otros se aceptan con
// un 200 y se ignoran, porque responder error haría que los reintentara.
const evento = String(cuerpo.event || cuerpo.event_type || '').trim();
const llamada = (cuerpo.call && typeof cuerpo.call === 'object') ? cuerpo.call : cuerpo;

return [{ json: {
  evento,
  es_analisis: evento === 'call_analyzed',
  llamada,
  directus_base_url: cfg.directus_base_url,
  canal: cfg.canal,
  tenant_timezone: cfg.tenant_timezone,
  _raw: crudo,
  _sig: String(headers['x-retell-signature'] || ''),
  _secret: String(cfg.retell_api_key || ''),
  _require_signature: String(cfg.require_signature).toLowerCase() === 'true',
} }];

// El veredicto de la firma se escribe SIEMPRE, valga o no valga y se exija o no.
// La lección de WhatsApp: una comprobación de seguridad que no se puede observar
// no está funcionando, se está acumulando. Aquí sale en cada ejecución.
const d = $json;
const esperado = String(d._hmac || '');
const recibida = String(d._sig || '').replace(/^v\d+=/, '').trim();

let firma = 'no_verificada';
let firma_motivo = null;

if (!d._secret || d._secret.startsWith('REPLACE_')) {
  firma_motivo = 'no hay RETELL_API_KEY en el tenant';
} else if (!recibida) {
  firma = 'ausente'; firma_motivo = 'la petición no trae x-retell-signature';
} else if (!esperado) {
  firma_motivo = 'el nodo Crypto no devolvió _hmac';
} else {
  // Comparación en tiempo constante: una comparación normal filtra el prefijo
  // correcto por el tiempo que tarda en fallar.
  const a = esperado, b = recibida;
  let dif = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    dif |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  }
  firma = dif === 0 ? 'valida' : 'invalida';
  if (dif !== 0) firma_motivo = 'el HMAC no coincide';
}

const descartar = d._require_signature && firma !== 'valida';

const salida = { ...d, firma, firma_motivo, descartar };
// El secreto y el cuerpo crudo no siguen viajando por la ejecución.
delete salida._secret; delete salida._raw; delete salida._sig; delete salida._hmac;
return [{ json: salida }];

// Un evento que no es el análisis, o uno con firma inválida cuando se exige.
// Se contesta 200 a propósito: un error haría que Retell lo reintentara en bucle,
// y no hay nada que reintentar.
const d = $json;
return [{ json: { ok: true, guardada: false,
  motivo: d.descartar ? `firma ${d.firma}` : `evento ${d.evento || 'desconocido'}`,
  firma: d.firma, firma_motivo: d.firma_motivo || null } }];

// De la forma de Retell a la nuestra. Todo con alternativas: este contrato lo
// define otra empresa y cambiará sin avisarnos, así que un campo que se mueva
// tiene que dejar la nota coja, nunca tumbar el webhook.
const d = $json;
const c = d.llamada || {};
const analisis = (c.call_analysis && typeof c.call_analysis === 'object') ? c.call_analysis : {};
const extra = (analisis.custom_analysis_data && typeof analisis.custom_analysis_data === 'object')
  ? analisis.custom_analysis_data : {};

const limpio = (v) => (v === undefined || v === null) ? null : (String(v).trim() || null);
const corto = (v, max) => { const s = limpio(v); return s ? s.slice(0, max) : null; };

// Mismo formato que WhatsApp (E.164 sin '+') para que un cliente que llama y otro
// que escribe sean EL MISMO contacto.
const telefono = (limpio(c.from_number) || '').replace(/[^\d]/g, '') || null;

const ms = Number(c.start_timestamp) || 0;
const fin = Number(c.end_timestamp) || 0;
const start_at = ms ? new Date(ms).toISOString() : new Date().toISOString();
let duracion = Number(c.duration_ms);
if (!Number.isFinite(duracion) || duracion <= 0) duracion = (fin && ms) ? (fin - ms) : 0;

const seguimiento = extra.requiere_seguimiento;
const esSi = (v) => v === true || ['true', 'si', 'sí', 'yes', '1'].includes(String(v).trim().toLowerCase());

return [{ json: {
  directus_base_url: d.directus_base_url,
  call_id: limpio(c.call_id) || limpio(c.callId),
  telefono,
  session_key: telefono ? `${d.canal || 'voz'}:${telefono}` : null,
  start_at,
  duracion_segundos: Math.max(0, Math.round(duracion / 1000)),
  direccion: String(c.direction || 'inbound').toLowerCase() === 'outbound' ? 'saliente' : 'entrante',
  motivo: corto(extra.motivo || extra.reason, 255),
  resultado: corto(extra.resultado || extra.outcome, 255),
  // El resumen es lo ÚNICO que sobrevive: en la plataforma de voz el audio y la
  // transcripción se borran con su retención corta.
  resumen: limpio(analisis.call_summary || extra.resumen),
  requiere_seguimiento: esSi(seguimiento),
  firma: d.firma,
}}];

// El webhook se reintenta, así que esto es lo NORMAL, no un error. `call_id` es
// UNIQUE en Directus por si dos reintentos llegan a la vez y los dos pasan por
// aquí antes de que ninguno escriba: la restricción es la que de verdad manda.
const n = $('Code · Normalizar').first().json;
return [{ json: { ok: true, guardada: false, motivo: 'ya existía', call_id: n.call_id } }];

// El contacto lo resuelve el MISMO sub-workflow que usan las tools (17, con
// sin_contexto: no hacen falta sus citas ni sus tareas aquí), para que la nota y
// la conversación no puedan discrepar sobre quién llamó.
const n = $('Code · Normalizar').first().json;
const r = $json || {};
const contact_id = r.contact_id || (r.contact && r.contact.id) || null;

return [{ json: {
  directus_base_url: n.directus_base_url,
  fila: {
    call_id: n.call_id,
    contact_id,
    telefono: n.telefono,
    session_key: n.session_key,
    start_at: n.start_at,
    duracion_segundos: n.duracion_segundos,
    direccion: n.direccion,
    motivo: n.motivo,
    resultado: n.resultado,
    resumen: n.resumen,
    requiere_seguimiento: n.requiere_seguimiento,
  },
}}];

// La respuesta dice la VERDAD sobre lo que ha pasado, y eso no es cosmético:
// Retell reintenta ante un error, y con la retención corta ese reintento es la
// única red que queda si Directus estaba caído. Mentir con un 200 alegre
// convertiría un fallo recuperable en un resumen perdido para siempre.
const n = $('Code · Normalizar').first().json;
const resp = $json || {};
const code = Number(resp.statusCode || 0);
const ok = code >= 200 && code < 300;
const creada = ok ? ((resp.body && resp.body.data && resp.body.data.id) || null) : null;

if (!ok) {
  throw new Error(`No se pudo guardar la nota de la llamada ${n.call_id}: `
    + `Directus devolvió ${code}. Retell reintentará.`);
}
return [{ json: { ok: true, guardada: true, call_id: n.call_id, id: creada } }];
